package com.sanctuarygames.createtransit;
import com.sanctuarygames.createtransit.elevator.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.level.block.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder("createtransit") @PrefixGameTestTemplate(false)
public final class ElevatorLightingGameTests {
 static void check(boolean ok,String message){if(!ok)throw new GameTestAssertException(message);}
 @GameTest(template="empty",timeoutTicks=40)
 public static void connected_ring_tracks_edges_diagonals_rotations_and_removal(GameTestHelper h){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4,3,4));var b=ElevatorRegistry.CEILING_RING.get();for(var q:new BlockPos[]{p,p.east(),p.south()})l.setBlock(q,b.defaultBlockState(),3);var s=l.getBlockState(p);check(s.getValue(ElevatorRingBlock.EAST)&&s.getValue(ElevatorRingBlock.SOUTH)&&!s.getValue(ElevatorRingBlock.SE),"L-shaped ring detects missing diagonal");check(ElevatorCeilingGeometry.lamps(s).size()==4,"L-shape contains two outer sides and two inner-corner segments");l.setBlock(p.east().south(),b.defaultBlockState(),3);s=l.getBlockState(p);check(s.getValue(ElevatorRingBlock.SE)&&ElevatorCeilingGeometry.lamps(s).size()==2,"Complete 2x2 ring removes inner dividers");for(var rotation:Rotation.values()){var turned=s.rotate(rotation);Direction e=rotation.rotate(Direction.EAST),south=rotation.rotate(Direction.SOUTH);check(turned.getValue(ElevatorRingBlock.side(e))&&turned.getValue(ElevatorRingBlock.side(south)),"Ring joints rotate with schematic");check(ElevatorCeilingGeometry.lamps(turned).equals(ElevatorCeilingGeometry.lamps(s)),"Local lamp geometry follows rotated facing and connections");}l.destroyBlock(p.east().south(),false);check(!l.getBlockState(p).getValue(ElevatorRingBlock.SE),"Diagonal removal updates corner without a cardinal notification");l.destroyBlock(p.east(),false);check(!l.getBlockState(p).getValue(ElevatorRingBlock.EAST),"Removing adjacent module restores exposed edge");h.succeed();}
 @GameTest(template="elevator_shaft",batch="elevators",timeoutTicks=800)
 public static void all_new_roof_lights_move_dye_and_restore_with_faster_through_elevator(GameTestHelper h){var d=ElevatorGameTests.fixture(h,true,true);var a=d.anchor();var blocks=new net.minecraft.world.level.block.Block[]{ElevatorRegistry.CEILING_STRIP.get(),ElevatorRegistry.CEILING_DOUBLE_STRIP.get(),ElevatorRegistry.CEILING_PANEL.get(),ElevatorRegistry.CEILING_BULB.get(),ElevatorRegistry.CEILING_RING.get()};var positions=new BlockPos[]{a.offset(0,4,-1),a.offset(1,4,-1),a.offset(2,4,-1),a.offset(0,4,0),a.offset(1,4,0)};for(int i=0;i<blocks.length;i++){var s=blocks[i].defaultBlockState();h.getLevel().setBlock(positions[i],s,3);((ElevatorPartEntity)h.getLevel().getBlockEntity(positions[i])).setColors(14,3);check(s.getLightEmission(h.getLevel(),positions[i])==12,"Each new roof fixture emits light");check(!ElevatorCeilingGeometry.lamps(s).isEmpty(),"Each fixture has luminous surfaces");}check(d.assemble(),"Every new ceiling fixture assembles as part of cabin");d.requestFloor(a.getY()+12);h.onEachTick(()->{if(d.phase()==ElevatorDriveEntity.IDLE&&Math.abs(d.offset()-12)<.001){ElevatorGameTests.sides(d,false,true);ElevatorGameTests.restored(d);for(int i=0;i<blocks.length;i++){var p=positions[i].above(12);check(h.getLevel().getBlockState(p).is(blocks[i]),"Correct light variant restores at destination");var be=(ElevatorPartEntity)h.getLevel().getBlockEntity(p);check(be.paint()==14&&be.accent()==3,"Housing and lamp dye survive moving restoration");}h.succeed();}});}
}
